type podSpecDescriptionMetadata struct {
	description string
	minItems    int
	maxItems    int
}

func podSpecWithDescriptions(object schema.NestedBlockObject) schema.NestedBlockObject {
	return podSpecNestedBlockObjectWithDescriptions("spec", object)
}

func podSpecNestedBlockObjectWithDescriptions(path string, object schema.NestedBlockObject) schema.NestedBlockObject {
	attributes := make(map[string]schema.Attribute, len(object.Attributes))
	for name, attribute := range object.Attributes {
		attributes[name] = podSpecAttributeWithDescriptions(path+"."+name, attribute)
	}
	blocks := make(map[string]schema.Block, len(object.Blocks))
	for name, block := range object.Blocks {
		blocks[name] = podSpecBlockWithDescriptions(path+"."+name, block)
	}
	object.Attributes = attributes
	object.Blocks = blocks
	return object
}

func podSpecNestedAttributeObjectWithDescriptions(path string, object schema.NestedAttributeObject) schema.NestedAttributeObject {
	attributes := make(map[string]schema.Attribute, len(object.Attributes))
	for name, attribute := range object.Attributes {
		attributes[name] = podSpecAttributeWithDescriptions(path+"."+name, attribute)
	}
	object.Attributes = attributes
	return object
}

func podSpecAttributeWithDescriptions(path string, attribute schema.Attribute) schema.Attribute {
	switch value := attribute.(type) {
	case schema.BoolAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		return value
	case schema.Int64Attribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		return value
	case schema.ListAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		if _, ok := value.ElementType.(types.ObjectType); ok {
			description = podSpecAppendSentence(description, podSpecInlineChildDescriptions(path))
			description = podSpecAppendSentence(description, podSpecInlineRequiredChild(path))
		}
		value.Description, value.MarkdownDescription = description, description
		return value
	case schema.ListNestedAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		value.NestedObject = podSpecNestedAttributeObjectWithDescriptions(path, value.NestedObject)
		return value
	case schema.MapAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		return value
	case schema.MapNestedAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		value.NestedObject = podSpecNestedAttributeObjectWithDescriptions(path, value.NestedObject)
		return value
	case schema.ObjectAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		return value
	case schema.SetAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		return value
	case schema.SetNestedAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		value.NestedObject = podSpecNestedAttributeObjectWithDescriptions(path, value.NestedObject)
		return value
	case schema.SingleNestedAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		value.Attributes = podSpecNestedAttributeObjectWithDescriptions(path, schema.NestedAttributeObject{Attributes: value.Attributes}).Attributes
		return value
	case schema.StringAttribute:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		return value
	default:
		return attribute
	}
}

func podSpecBlockWithDescriptions(path string, block schema.Block) schema.Block {
	switch value := block.(type) {
	case schema.ListNestedBlock:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		value.NestedObject = podSpecNestedBlockObjectWithDescriptions(path, value.NestedObject)
		return value
	case schema.SetNestedBlock:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		value.NestedObject = podSpecNestedBlockObjectWithDescriptions(path, value.NestedObject)
		return value
	case schema.SingleNestedBlock:
		description := podSpecApplyDescription(path, value.Description, true)
		value.Description, value.MarkdownDescription = description, description
		nested := podSpecNestedBlockObjectWithDescriptions(path, schema.NestedBlockObject{Attributes: value.Attributes, Blocks: value.Blocks})
		value.Attributes = nested.Attributes
		value.Blocks = nested.Blocks
		return value
	default:
		return block
	}
}

func podSpecApplyDescription(path, existing string, includeCardinality bool) string {
	description := strings.TrimSpace(existing)
	metadata, ok := podSpecDescriptionByPath[path]
	if !ok {
		return description
	}
	if metadata.description != "" {
		description = podSpecMergeLegacyAndNativeDescription(metadata.description, description)
	}
	if includeCardinality {
		if hint := podSpecCardinalityHint(metadata.minItems, metadata.maxItems); hint != "" {
			description = podSpecAppendSentence(description, hint)
		}
	}
	return description
}

func podSpecMergeLegacyAndNativeDescription(legacy, native string) string {
	legacyRaw := legacy
	legacyTrimmed := strings.TrimSpace(legacy)
	nativeTrimmed := strings.TrimSpace(native)
	if legacyTrimmed == "" {
		return nativeTrimmed
	}
	if nativeTrimmed == "" || nativeTrimmed == legacyRaw || nativeTrimmed == legacyTrimmed {
		return legacyRaw
	}

	suffix := nativeTrimmed
	if strings.HasPrefix(nativeTrimmed, legacyTrimmed) {
		suffix = strings.TrimSpace(strings.TrimPrefix(nativeTrimmed, legacyTrimmed))
	} else if strings.Contains(nativeTrimmed, legacyTrimmed) {
		suffix = strings.TrimSpace(strings.Replace(nativeTrimmed, legacyTrimmed, "", 1))
	} else {
		legacySentenceSet := map[string]struct{}{}
		for _, sentence := range podSpecDescriptionSentences(legacyTrimmed) {
			legacySentenceSet[podSpecNormalizeSentence(sentence)] = struct{}{}
		}
		nativeOnly := make([]string, 0)
		for _, sentence := range podSpecDescriptionSentences(nativeTrimmed) {
			if _, exists := legacySentenceSet[podSpecNormalizeSentence(sentence)]; exists {
				continue
			}
			nativeOnly = append(nativeOnly, sentence)
		}
		suffix = strings.TrimSpace(strings.Join(nativeOnly, " "))
	}
	suffix = strings.TrimSpace(strings.TrimLeft(suffix, " .,:;-"))

	if suffix == "" {
		return legacyRaw
	}
	return podSpecAppendSentence(legacyRaw, suffix)
}

func podSpecCardinalityHint(minimum, maximum int) string {
	switch {
	case minimum > 0 && maximum > 0 && minimum == maximum:
		return "Exactly " + strconv.Itoa(minimum) + " item(s) are allowed."
	case minimum > 0 && maximum > 0:
		return "At least " + strconv.Itoa(minimum) + " and at most " + strconv.Itoa(maximum) + " item(s) are allowed."
	case minimum > 0:
		return "At least " + strconv.Itoa(minimum) + " item(s) are required."
	case maximum > 0:
		return "At most " + strconv.Itoa(maximum) + " item(s) are allowed."
	default:
		return ""
	}
}

func podSpecAppendSentence(description, sentence string) string {
	sentence = strings.TrimSpace(sentence)
	if sentence == "" {
		return description
	}
	if description == "" {
		return sentence
	}
	if strings.Contains(description, sentence) {
		return description
	}
	if strings.HasSuffix(description, " ") {
		return description + sentence
	}
	return strings.TrimRight(description, " ") + " " + sentence
}

func podSpecDescriptionSentences(description string) []string {
	parts := strings.Split(description, ". ")
	sentences := make([]string, 0, len(parts))
	for index, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if index < len(parts)-1 && !strings.HasSuffix(part, ".") {
			part += "."
		}
		sentences = append(sentences, part)
	}
	return sentences
}

func podSpecNormalizeSentence(sentence string) string {
	return strings.ToLower(strings.Trim(strings.TrimSpace(sentence), " ."))
}

func podSpecInlineChildDescriptions(path string) string {
	prefix := path + "."
	lines := make([]string, 0)
	for childPath, metadata := range podSpecDescriptionByPath {
		if metadata.description == "" || !strings.HasPrefix(childPath, prefix) {
			continue
		}
		child := strings.TrimPrefix(childPath, prefix)
		if strings.Contains(child, ".") {
			continue
		}
		lines = append(lines, "`"+child+"`: "+metadata.description)
	}
	if len(lines) == 0 {
		return ""
	}
	sort.Strings(lines)
	return "Nested object fields: " + strings.Join(lines, " ")
}

func podSpecInlineRequiredChild(path string) string {
	child, ok := podSpecInlineRequiredChildren[path]
	if !ok {
		return ""
	}
	return "Each object must set `" + child + "`; `{}` is not valid."
}

